import { BaseApi } from "../utils/base-api.ts";
import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import type { IFriend } from "../models/types.ts";
import { EnhancedApi } from "../constants/api.ts";

export interface IFriendsResponse {
    friends: IFriend[];
    total: number;
    page: number;
    limit: number;
}

export class FriendsBasicApi extends BaseApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    public async getFriends(params?: { category?: string; page?: number; limit?: number }): Promise<IFriendsResponse> {
        return this.get<IFriendsResponse>(EnhancedApi.FRIENDS, params);
    }

    public async getFriend(friendId: string): Promise<IFriend | null> {
        const response = await this.get<{ friend: IFriend | null }>(
            EnhancedApi.FRIENDS_DETAIL.replace("{userId}", encodeURIComponent(friendId)),
        );
        return response.friend;
    }

    public async checkFriendship(otherUserId: string): Promise<boolean> {
        const response = await this.get<{ is_friend: boolean }>(
            EnhancedApi.FRIENDS_CHECK.replace("{userId}", encodeURIComponent(otherUserId)),
        );
        return response.is_friend ?? false;
    }

    public async setRemark(friendId: string, remark: string): Promise<boolean> {
        try {
            await this.put<{ status: string }>(
                EnhancedApi.FRIENDS_REMARK.replace("{userId}", encodeURIComponent(friendId)),
                { remark },
            );
            return true;
        } catch {
            return false;
        }
    }

    public async deleteFriend(friendId: string): Promise<boolean> {
        const response = await this.deleteRequest<{ status: string; error?: string }>(
            EnhancedApi.FRIENDS_DELETE.replace("{userId}", encodeURIComponent(friendId)),
        );
        return response.status === "ok";
    }
}
